CREATE TABLE construction_knowledge_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,code varchar(80) NOT NULL,title varchar(300) NOT NULL,discipline varchar(120) NOT NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,code),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id));
CREATE TABLE construction_knowledge_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,knowledge_id uuid NOT NULL,version_number integer NOT NULL CHECK(version_number>0),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','review_required','approved','superseded')),country_code char(2) NOT NULL CHECK(country_code~'^[A-Z]{2}$'),region_code varchar(80),construction_methods jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(construction_methods)='array'),execution_rules jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(execution_rules)='array'),engineering_constraints jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(engineering_constraints)='array'),compatibility_rules jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(compatibility_rules)='array'),environmental_requirements jsonb NOT NULL DEFAULT'{}'CHECK(jsonb_typeof(environmental_requirements)='object'),substrate_requirements jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(substrate_requirements)='array'),quality_requirements jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(quality_requirements)='array'),inspection_rules jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(inspection_rules)='array'),acceptance_criteria jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(acceptance_criteria)='array'),safety_requirements jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(safety_requirements)='array'),regional_regulations jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(regional_regulations)='array'),approved_at timestamptz,approved_by uuid,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,knowledge_id,version_number),FOREIGN KEY(tenant_id,knowledge_id)REFERENCES construction_knowledge_records(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id),CHECK((status='approved'AND approved_at IS NOT NULL AND approved_by IS NOT NULL)OR status<>'approved'));
CREATE TABLE engineering_norms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,code varchar(80) NOT NULL,title varchar(300) NOT NULL,country_code char(2) NOT NULL CHECK(country_code~'^[A-Z]{2}$'),region_code varchar(80),discipline varchar(120) NOT NULL,work_type varchar(80) NOT NULL,technology_version_id uuid NOT NULL,knowledge_version_id uuid NOT NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE NULLS NOT DISTINCT(tenant_id,country_code,region_code,code),FOREIGN KEY(tenant_id,technology_version_id)REFERENCES execution_technology_versions(tenant_id,id),FOREIGN KEY(tenant_id,knowledge_version_id)REFERENCES construction_knowledge_versions(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id));
CREATE TABLE engineering_norm_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,norm_id uuid NOT NULL,revision_number integer NOT NULL CHECK(revision_number>0),execution_stage varchar(160) NOT NULL,effective_from date NOT NULL,effective_to date,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','review_required','ready_for_approval','approved','superseded','cancelled')),authoritative boolean NOT NULL DEFAULT false,is_current boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,approved_at timestamptz,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,norm_id,revision_number),FOREIGN KEY(tenant_id,norm_id)REFERENCES engineering_norms(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id),CHECK(effective_to IS NULL OR effective_to>=effective_from),CHECK((status='approved'AND authoritative AND approved_at IS NOT NULL AND approved_by IS NOT NULL)OR status<>'approved'));
CREATE UNIQUE INDEX uq_engineering_norm_current ON engineering_norm_revisions(tenant_id,norm_id)WHERE is_current;
CREATE TABLE engineering_norm_parameters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,revision_id uuid NOT NULL,code varchar(80) NOT NULL,label varchar(200) NOT NULL,unit_code varchar(40) NOT NULL,data_type text NOT NULL CHECK(data_type IN('decimal','integer','boolean','enum')),minimum_value numeric(20,8),maximum_value numeric(20,8),allowed_values jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(allowed_values)='array'),required boolean NOT NULL DEFAULT true,default_value jsonb,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,UNIQUE(tenant_id,revision_id,code),FOREIGN KEY(tenant_id,revision_id)REFERENCES engineering_norm_revisions(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),CHECK(minimum_value IS NULL OR maximum_value IS NULL OR minimum_value<=maximum_value));
CREATE TABLE engineering_norm_layers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,revision_id uuid NOT NULL,sequence integer NOT NULL CHECK(sequence>0),code varchar(80) NOT NULL,name varchar(200) NOT NULL,layer_kind varchar(80) NOT NULL,requirements jsonb NOT NULL DEFAULT'{}'CHECK(jsonb_typeof(requirements)='object'),minimum_drying_hours numeric(12,3)CHECK(minimum_drying_hours>=0),inspection_required boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,UNIQUE(tenant_id,revision_id,sequence),UNIQUE(tenant_id,revision_id,code),FOREIGN KEY(tenant_id,revision_id)REFERENCES engineering_norm_revisions(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id));
CREATE TABLE engineering_norm_demands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,revision_id uuid NOT NULL,demand_kind text NOT NULL CHECK(demand_kind IN('material_requirement','labor','machine')),requirement_code varchar(120) NOT NULL,description varchar(1000) NOT NULL,output_unit_code varchar(40) NOT NULL,formula jsonb NOT NULL CHECK(jsonb_typeof(formula)='object'),qualification varchar(300),crew_composition jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(crew_composition)='array'),shift_assumptions jsonb NOT NULL DEFAULT'{}'CHECK(jsonb_typeof(shift_assumptions)='object'),machine_requirements jsonb NOT NULL DEFAULT'{}'CHECK(jsonb_typeof(machine_requirements)='object'),engineering_requirements jsonb NOT NULL DEFAULT'{}'CHECK(jsonb_typeof(engineering_requirements)='object'),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,UNIQUE(tenant_id,revision_id,demand_kind,requirement_code),FOREIGN KEY(tenant_id,revision_id)REFERENCES engineering_norm_revisions(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id));
CREATE TABLE approved_engineering_norm_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,norm_id uuid NOT NULL,revision_id uuid NOT NULL,revision_number integer NOT NULL,content jsonb NOT NULL CHECK(jsonb_typeof(content)='object'AND pg_column_size(content)<=4194304),content_fingerprint char(64) NOT NULL,schema_version varchar(40) NOT NULL DEFAULT'engineering-norm-v1',approved_at timestamptz NOT NULL DEFAULT now(),approved_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,revision_id),FOREIGN KEY(tenant_id,norm_id)REFERENCES engineering_norms(tenant_id,id),FOREIGN KEY(tenant_id,revision_id)REFERENCES engineering_norm_revisions(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id));
CREATE FUNCTION protect_approved_engineering_norm_snapshot()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION'APPROVED_ENGINEERING_NORM_SNAPSHOT_IMMUTABLE';END$$;CREATE TRIGGER immutable_approved_engineering_norm_snapshot BEFORE UPDATE OR DELETE ON approved_engineering_norm_snapshots FOR EACH ROW EXECUTE FUNCTION protect_approved_engineering_norm_snapshot();
CREATE FUNCTION protect_approved_engineering_norm_content()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE rid uuid;state text;BEGIN rid=CASE WHEN TG_OP='DELETE'THEN OLD.revision_id ELSE NEW.revision_id END;SELECT status INTO state FROM engineering_norm_revisions WHERE id=rid;IF state IN('approved','superseded')THEN RAISE EXCEPTION'APPROVED_ENGINEERING_NORM_IMMUTABLE';END IF;IF TG_OP='DELETE'THEN RETURN OLD;END IF;RETURN NEW;END$$;CREATE TRIGGER immutable_engineering_norm_parameters BEFORE INSERT OR UPDATE OR DELETE ON engineering_norm_parameters FOR EACH ROW EXECUTE FUNCTION protect_approved_engineering_norm_content();CREATE TRIGGER immutable_engineering_norm_layers BEFORE INSERT OR UPDATE OR DELETE ON engineering_norm_layers FOR EACH ROW EXECUTE FUNCTION protect_approved_engineering_norm_content();CREATE TRIGGER immutable_engineering_norm_demands BEFORE INSERT OR UPDATE OR DELETE ON engineering_norm_demands FOR EACH ROW EXECUTE FUNCTION protect_approved_engineering_norm_content();
CREATE FUNCTION protect_approved_construction_knowledge()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.status IN('approved','superseded')THEN RAISE EXCEPTION'APPROVED_CONSTRUCTION_KNOWLEDGE_IMMUTABLE';END IF;RETURN CASE WHEN TG_OP='DELETE'THEN OLD ELSE NEW END;END$$;CREATE TRIGGER immutable_approved_construction_knowledge BEFORE UPDATE OR DELETE ON construction_knowledge_versions FOR EACH ROW EXECUTE FUNCTION protect_approved_construction_knowledge();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['construction_knowledge_records','construction_knowledge_versions','engineering_norms','engineering_norm_revisions','engineering_norm_parameters','engineering_norm_layers','engineering_norm_demands','approved_engineering_norm_snapshots']LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_%I ON %I USING(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)WITH CHECK(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)',t,t);END LOOP;END$$;
CREATE INDEX idx_knowledge_region ON construction_knowledge_versions(tenant_id,country_code,region_code,status);CREATE INDEX idx_engineering_norm_region ON engineering_norms(tenant_id,country_code,region_code,discipline,work_type);CREATE INDEX idx_engineering_norm_revision ON engineering_norm_revisions(tenant_id,norm_id,revision_number DESC);CREATE INDEX idx_engineering_norm_demands ON engineering_norm_demands(tenant_id,revision_id,demand_kind);
INSERT INTO permissions(code,description)VALUES('engineering_norms.create','Create construction knowledge and engineering norms'),('engineering_norms.read','Read construction knowledge and engineering norms'),('engineering_norms.edit','Edit draft construction knowledge and engineering norms'),('engineering_norms.review','Review construction knowledge and engineering norms'),('engineering_norms.approve','Approve authoritative construction knowledge and engineering norms'),('engineering_norms.evaluate','Evaluate approved engineering norms'),('engineering_norms.snapshots.read','Read approved engineering norm snapshots')ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE(r.code IN('tenant_admin','project_manager')AND p.code LIKE'engineering_norms.%')OR(r.code='employee'AND p.code IN('engineering_norms.read','engineering_norms.evaluate'))OR(r.code='read_only'AND p.code IN('engineering_norms.read','engineering_norms.snapshots.read'))ON CONFLICT DO NOTHING;
